def n(v,unit='',dec=0,prefix=''):return f'<span class="count" data-v="{v}" data-dec="{dec}" data-pre="{prefix}">{prefix}{v}</span><span class="unit">{unit}</span>'
def card(label,value,off=4,cls=''):return f'<div class="card reveal {cls}" data-beat="{off}"><div class="label">{label}</div><div class="value">{value}</div></div>'
def tag(t,off=4):return f'<div class="tag reveal" data-beat="{off}">{t}</div>'
