 paths={'front':('M70 44 H165 L185 136',190,192,67),'roof':('M658 43 H570 L505 108',497,112,58),'cockpit':('M650 55 H530 L433 152',375,201,72)};path,x,y,r=paths[kind]
 return f'<svg class="annotations" viewBox="0 0 750 400" aria-label="{kind} annotation"><defs><marker id="arrow-{kind}" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="none" stroke="#173653" stroke-width="1.2"/></marker></defs><path class="anno-path" d="{path}" marker-end="url(#arrow-{kind})"/><circle class="anno-circle" cx="{x}" cy="{y}" r="{r}"/></svg>'
