css='''@font-face{font-family:Modern;src:url(assets/fonts/Regular.ttf);font-weight:400}@font-face{font-family:Modern;src:url(assets/fonts/Semibold.ttf);font-weight:600}@font-face{font-family:Modern;src:url(assets/fonts/Light.ttf);font-weight:300}*{box-sizing:border-box}body{margin:0;background:#F3F2EF;color:#173653;font-family:Modern,sans-serif}#composition{position:relative;width:1920px;height:1080px;overflow:hidden;background:#F3F2EF}.scene{position:absolute;inset:0;opacity:0;background:#F3F2EF}.scene-content{width:100%;height:100%;padding:52px 70px 192px;display:flex;flex-direction:column;gap:42px}header{display:flex;justify-content:space-between;border-bottom:1px solid #ADB9C3;padding-bottom:20px;font-size:26px;letter-spacing:4px;font-weight:600}.layout{display:grid;grid-template-columns:610px 1110px;gap:60px;flex:1;min-height:0}.copy{display:flex;flex-direction:column;gap:18px;min-width:0}.kicker{font-size:25px;line-height:1.45;letter-spacing:2px;min-height:38px;color:#46627D}h1{font-size:77px;font-weight:300;line-height:1.15;letter-spacing:-2px;margin:0;min-height:190px;padding-bottom:12px}.cards{display:flex;flex-direction:column;gap:16px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{background:#FFFFFF;border-left:3px solid #46627D;padding:16px 20px;min-width:0}.label{font-size:27px;line-height:1.3;color:#46627D;letter-spacing:.5px}.value{font-size:84px;font-weight:600;line-height:1.15;font-variant-numeric:tabular-nums;color:#173653;white-space:nowrap;letter-spacing:-2px;margin-top:8px}.unit{font-size:29px;font-weight:400;letter-spacing:0;margin-left:9px}.value .unit{display:block;margin-left:0;line-height:1.2}.card.wide{grid-column:1/-1}.wide .value .unit{display:inline;margin-left:12px}.tag{padding:20px 24px;background:#E5E8E9;font-size:30px;font-weight:400;line-height:1.4;border-left:3px solid #46627D}.consumption .value{font-size:46px;letter-spacing:-1px}.consumption .value .unit:empty{display:none}.dash{padding:0 4px}.dimensions{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.dimensions .card{padding:12px 10px}.dimensions .label{font-size:22px}.dimensions .value{font-size:61px;letter-spacing:-2px}.dimensions .unit{font-size:25px}.sales .value{font-size:76px}.visual{display:flex;flex-direction:column;gap:20px;min-width:0;padding-top:14px}.callout{font-size:29px;line-height:1.3;letter-spacing:3px;color:#46627D;border-bottom:1px solid #ADB9C3;padding-bottom:15px}.photo-stage{position:relative;width:1110px;height:560px;flex:none;display:flex;align-items:center;justify-content:center}.photo{width:100%;height:100%;object-fit:contain;display:block}.photo-note{font-size:25px;line-height:1.4;color:#46627D}.annotations{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible;opacity:.7}.anno-path,.anno-circle{fill:none;stroke:#173653;stroke-width:1.2px;vector-effect:non-scaling-stroke}.reveal{opacity:0}#captions{position:absolute;z-index:100;bottom:36px;left:85px;right:85px;min-height:130px;display:flex;align-items:end;justify-content:center;font-size:62px;line-height:1.2;text-align:center;font-weight:400;color:#173653;letter-spacing:-.7px}#captions span{background:#F3F2EF;padding:4px 16px;box-decoration-break:clone;-webkit-box-decoration-break:clone}#chapter-rail{position:absolute;left:70px;bottom:210px;width:1780px;height:2px;background:#D5DBDF;z-index:99}#chapter-fill{height:2px;background:#46627D;width:100%;transform-origin:left}.brand-accent{position:absolute;top:0;left:70px;width:180px;height:6px;background:#173653;z-index:100}'''
js='''const SPEC=__SPEC__,CAPTIONS=__CAPTIONS__;window.__timelines=window.__timelines||{};const tl=gsap.timeline({paused:true}),counts=[];const T=.5;
SPEC.pages.forEach((s,i)=>{const el=document.getElementById('s'+i);tl.fromTo(el,{opacity:0},{opacity:1,duration:.5,ease:'power1.out',immediateRender:false},s.a);if(i<SPEC.pages.length-1)tl.to(el,{opacity:0,duration:.01},s.b+.49);
 el.querySelectorAll('.reveal').forEach(x=>{const at=s.a+Number(x.dataset.beat||0)*T;tl.fromTo(x,{opacity:0,x:18},{opacity:1,x:0,duration:.6,ease:'power2.out',immediateRender:false},at);});
 el.querySelectorAll('.count').forEach(x=>{const at=s.a+Number(x.closest('.reveal')?.dataset.beat||0)*T;counts.push({el:x,at,end:at+1.8,v:Number(x.dataset.v),dec:Number(x.dataset.dec),pre:x.dataset.pre||''});});
 el.querySelectorAll('.anno-path,.anno-circle').forEach((x,j)=>{const length=x.getTotalLength();x.style.strokeDasharray=length;x.style.strokeDashoffset=length;tl.fromTo(x,{strokeDashoffset:length},{strokeDashoffset:0,duration:1.5,ease:'power2.out',immediateRender:false},s.a+2+j*2);});
});tl.fromTo('#chapter-fill',{scaleX:0},{scaleX:1,duration:90,ease:'none'},0);
const c=document.querySelector('#captions span');function textAt(t){counts.forEach(x=>{const q=Math.max(0,Math.min(1,(t-x.at)/(x.end-x.at))),v=x.v*(1-Math.pow(1-q,3));x.el.textContent=x.pre+(x.dec?v.toFixed(x.dec):Math.round(v).toLocaleString('en-US'));});const line=CAPTIONS.find(x=>t>=x.start&&t<x.end);c.textContent=line?line.text:'';}
tl.eventCallback('onUpdate',()=>textAt(tl.time()));window.__timelines['avatr11-b2b']=tl;window.FILM={spec:SPEC,captions:CAPTIONS,seek(t){t=Math.round(Math.max(0,Math.min(90,t))*30)/30;tl.time(t);textAt(t);}};window.FILM.seek(0);'''.replace('__SPEC__',json.dumps(dict(width=1920,height=1080,fps=30,bpm=120,duration=90,pages=pages))).replace('__CAPTIONS__',json.dumps(json.loads((p/'work/timing.json').read_text())))
(p/'index.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><title>AVATR11 · UNILAND B2B</title><style>{css}</style><body><main id="composition" data-composition-id="avatr11-b2b" data-start="0" data-duration="90" data-width="1920" data-height="1080" data-fps="30">'+''.join(parts)+'<div class="brand-accent" data-layout-ignore></div><div id="chapter-rail" data-layout-ignore><div id="chapter-fill"></div></div><div id="captions"><span></span></div><audio id="voice" src="assets/audio/voice.mp3" data-start="0" data-duration="90" data-volume="1" data-track-index="4"></audio><audio id="music" src="assets/audio/bgm.mp3" data-start="0" data-duration="90" data-volume=".65" data-track-index="5"></audio></main><script src="assets/gsap.min.js"></script><script>'+js+'</script></body></html>')
